begin;
create table if not exists public.shelters(id uuid primary key default gen_random_uuid(),name text not null,address text not null default '',contact_email text not null default '',created_at timestamptz not null default now());
create table if not exists public.shelter_partnership_codes(id uuid primary key default gen_random_uuid(),shelter_id uuid not null references public.shelters(id) on delete cascade,code_hash text not null unique check(char_length(code_hash)=64),expires_at timestamptz,used_at timestamptz,used_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.shelter_accounts(user_id uuid primary key references auth.users(id) on delete cascade,shelter_id uuid not null references public.shelters(id) on delete restrict,created_at timestamptz not null default now());
create table if not exists public.shelter_volunteer_activities(id uuid primary key default gen_random_uuid(),shelter_id uuid not null references public.shelters(id) on delete restrict,created_by uuid not null references public.shelter_accounts(user_id) on delete restrict,title text not null,summary text not null default '',description text not null,activity_type text not null,event_start_at timestamptz,event_end_at timestamptz,application_deadline timestamptz,capacity integer check(capacity is null or capacity>0),contact_email text,contact_phone text,status text not null default 'draft' check(status in('draft','published','suspended','closed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.shelter_accounts enable row level security;alter table public.shelter_volunteer_activities enable row level security;
create policy "shelter reads own binding" on public.shelter_accounts for select using(user_id=auth.uid());
create policy "shelter reads own activities" on public.shelter_volunteer_activities for select using(shelter_id=(select shelter_id from public.shelter_accounts where user_id=auth.uid()));
create policy "shelter inserts own activities" on public.shelter_volunteer_activities for insert with check(created_by=auth.uid() and shelter_id=(select shelter_id from public.shelter_accounts where user_id=auth.uid()));
create policy "shelter updates own activities" on public.shelter_volunteer_activities for update using(created_by=auth.uid() and shelter_id=(select shelter_id from public.shelter_accounts where user_id=auth.uid())) with check(created_by=auth.uid() and shelter_id=(select shelter_id from public.shelter_accounts where user_id=auth.uid()));
create or replace function public.bind_shelter_account(p_user_id uuid,p_code_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare v_shelter uuid; begin select shelter_id into v_shelter from shelter_partnership_codes where id=p_code_id and used_at is null and(expires_at is null or expires_at>now()) for update;if v_shelter is null then raise exception 'invalid code';end if;update profiles set role='shelter',class_id=null where id=p_user_id;insert into shelter_accounts(user_id,shelter_id) values(p_user_id,v_shelter) on conflict(user_id) do update set shelter_id=excluded.shelter_id;update shelter_partnership_codes set used_at=now(),used_by=p_user_id where id=p_code_id;end $$;
revoke all on function public.bind_shelter_account(uuid,uuid) from public,anon,authenticated;
commit;
